/**
 * @description TEMPLATE connection auth class for Connection Type = Apex Auth: a custom token login that a Named
 * Credential cannot do by itself. Rename it, set TOKEN_URL and the body of login() for your system, deploy it with its
 * test class, then on the connection pick Connection Type = Apex Auth and this class in Auth Class.
 * How it works: before each send Integration Hub calls authorize(). It reuses the cached token, or logs in to the
 * token URL through a Named Credential (here Partner_Login), reads access_token and expires_in, keeps the token in
 * IntegrationHubTokenCache and sets the Authorization header. After a 401 the hub calls it again with ctx.refresh =
 * true (log in again) and resends once.
 * No secret in code or in a field: the client Id and secret live in the External Credential of the Partner_Login Named
 * Credential (Authentication Protocol Custom, parameters ClientId and ClientSecret). Tick "Allow Formulas in HTTP
 * Body" on that Named Credential so the merge fields below are filled at send time, and give the External Credential
 * principal to Integration Hub Read and Integration Hub Admin (the send runs as the user who saved the record).
 * A CalloutException (the token URL is down, answers 5xx here, or times out) fails the send as temporary, so
 * auto-retry applies; any other exception fails the transaction for good (permanent) with your message.
 * @group Integration Hub
 */
public with sharing class IH_SampleConnectionAuth implements IntegrationHub.IConnectionAuth {

    /** Token URL: a Named Credential plus the path. Change Partner_Login and the path to yours. */
    @TestVisible
    private static final String TOKEN_URL = 'callout:Partner_Login/oauth/token';
    /** The token is kept this many seconds less than the system says, so it is never sent just as it expires. */
    private static final Integer SAFETY_SECONDS = 60;
    /** Used when the answer has no expires_in. */
    private static final Integer DEFAULT_SECONDS = 3600;

    /**
     * @description Adds the login to the request: a cached token, or a new one after a 401 or when none is cached.
     * @param ctx the request, the connection and refresh
     */
    // Setting Authorization here is the point of an auth class; the login itself goes through a Named Credential.
    @SuppressWarnings('PMD.ApexSuggestUsingNamedCred')
    public void authorize(IntegrationHub.AuthContext ctx) {
        Id connectionId = ctx.connection == null ? null : ctx.connection.Id;
        String token = ctx.refresh == true ? null : IntegrationHubTokenCache.cachedToken(connectionId);
        if (String.isBlank(token)) {
            token = login(connectionId);
        }
        ctx.request.setHeader('Authorization', 'Bearer ' + token);
    }

    /**
     * @description Logs in to the token URL and keeps the token for its life minus a minute.
     * @param connectionId the connection (the cache key)
     * @return the access token
     */
    @TestVisible
    private static String login(Id connectionId) {
        HttpRequest req = new HttpRequest();
        req.setEndpoint(TOKEN_URL);
        req.setMethod('POST');
        req.setTimeout(30000);
        req.setHeader('Content-Type', 'application/x-www-form-urlencoded');
        // Change to what your token URL expects. The merge fields read the External Credential at send time.
        req.setBody('grant_type=client_credentials&client_id={!$Credential.Partner_Login.ClientId}'
            + '&client_secret={!$Credential.Partner_Login.ClientSecret}');
        HttpResponse res = new Http().send(req);
        if (res.getStatusCode() >= 500) {
            // The token URL is down: a CalloutException makes it a temporary failure, so auto-retry sends it again.
            throw new CalloutException('the token URL answered HTTP ' + res.getStatusCode() + ' (temporary)');
        }
        if (res.getStatusCode() < 200 || res.getStatusCode() > 299) {
            throw new IntegrationHub.HubException('the token URL answered HTTP ' + res.getStatusCode() + ': '
                + String.valueOf(res.getBody()).abbreviate(200));
        }
        Map<String, Object> answer = parse(res.getBody());
        String token = answer == null ? null : (String) answer.get('access_token');
        if (String.isBlank(token)) {
            throw new IntegrationHub.HubException('the token URL answered without access_token.');
        }
        IntegrationHubTokenCache.putToken(connectionId, token, secondsOf(answer.get('expires_in')) - SAFETY_SECONDS);
        return token;
    }

    /**
     * @description The answer as a JSON object.
     * @param body the answer text
     * @return the object, or null when it is not a JSON object
     */
    @TestVisible
    private static Map<String, Object> parse(String body) {
        try {
            Object parsed = String.isBlank(body) ? null : JSON.deserializeUntyped(body);
            return parsed instanceof Map<String, Object> ? (Map<String, Object>) parsed : null;
        } catch (JSONException e) {
            return null;
        }
    }

    /**
     * @description expires_in as seconds (a number or a text); one hour when missing or not a number.
     * @param value the expires_in value
     * @return the seconds
     */
    @TestVisible
    private static Integer secondsOf(Object value) {
        try {
            return value == null ? DEFAULT_SECONDS : Decimal.valueOf(String.valueOf(value)).intValue();
        } catch (TypeException e) {
            return DEFAULT_SECONDS;
        }
    }
}
